Page-Navigation Actions: scroll / goto_url / go_back / wait
{
"type": "function",
"function": {
"name": "scroll",
"description": "Scroll the page or a specific scrollable element in the given direction. If
point_2d is provided, the scroll occurs on the element at that coordinate (useful for scrollable
sub-containers like sidebars, modals, or chat panels). Otherwise, scrolls the main page.",
"parameters": {
"type": "object",
"properties": {
"direction": {
"type": "string",
"enum": ["up", "down", "left", "right"],
"description": "Direction to scroll.",
"default": "down"
},
"amount": {
"type": "number",
"minimum": 0.0, "maximum": 1.0,
"description": "Scroll amount as a percentage of the viewport height (0.0 to 1.0). For
example, 0.5 means scroll by half a page.",
"default": 0.5
},
"point_2d": {
"type": "array",
"items": {"type": "number"},
"minItems": 2, "maxItems": 2,
"description": "Optional [x, y] pixel coordinates of the element to scroll within. If
omitted, scrolls the main page."
}
}
}
},
{
"type": "function",
"function": {
"name": "goto_url",
"description": "Navigate the current open tab to a specific URL. Use this to open a new webpage
directly in the current tab instead of clicking through links or typing in the address bar.",
"parameters": {
"type": "object",
"properties": {
"url": {
"type": "string",
"description": "The full URL to navigate to (e.g., \"https://www.example.com\")."
}
},
"required": ["url"]
}
},
{
"type": "function",
"function": {
"name": "go_back",
"description": "Navigate back to the previous page in the browser history. Equivalent to clicking
the browser's back button.",
"parameters": {"type": "object", "properties": {}}
}
},
{
"type": "function",
"function": {
"name": "wait",
"description": "Wait for a specified number of seconds before continuing. Use this when you need
to allow time for page content to load or for animations to complete.",
"parameters": {
"type": "object",
"properties": {
"seconds": {
"type": "integer",
"description": "Number of seconds to wait (integer value)",
"default": 3
}
}

Tab-Management Actions: new_tab / switch_tab / close_tab
{
"type": "function",
"function": {
"name": "new_tab",
"description": "Open a new blank browser tab. Use goto_url after switching to the new tab to
navigate to a specific URL.",
"parameters": {"type": "object", "properties": {}}
},
{
"type": "function",
"function": {
"name": "switch_tab",
"description": "Switch to a different browser tab by its index (0-based). Use this to navigate
between multiple open tabs.",
"parameters": {
"type": "object",
"properties": {
"tab_index": {
"type": "integer",
"description": "The 0-based index of the tab to switch to."
}
},
"required": ["tab_index"]
}
}
},
{
"type": "function",
"function": {
"name": "close_tab",
"description": "Close the current browser tab. If there are multiple tabs open, the browser will
switch to the nearest remaining tab.",
"parameters": {"type": "object", "properties": {}}
}
